const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];

let count = 0;
let maxRight = data[n]; // máximo das alturas à direita da posição atual (aluno N é sempre visível)

